import * as React from "react";
import { FunctionComponent, useMemo, type CSSProperties } from "react";
import * as styles from "./trip-menu-item.module.css";

export type TripMenuItem1Type = {
  className?: string;
  iconVector?: string;
  text?: string;

  /** Style props */
  iconBackgroundColor?: CSSProperties["backgroundColor"];
};

const TripMenuItem1: FunctionComponent<TripMenuItem1Type> = ({
  className = "",
  iconBackgroundColor,
  iconVector,
  text,
}) => {
  const iconStyle: CSSProperties = useMemo(() => {
    return {
      backgroundColor: iconBackgroundColor,
    };
  }, [iconBackgroundColor]);

  return (
    <div className={[styles.tripMenuItem, className].join(" ")}>
      <div className={styles.icon} style={iconStyle}>
        <img className={styles.iconVector} alt="" src={iconVector} />
      </div>
      <div className={styles.text}>{text}</div>
    </div>
  );
};

export default TripMenuItem1;
